        $nombre = $formCode === self::FORM_CERTIFICADO_UNIVERSITARIO
            ? self::TIPO_ACCION_CERTIFICADO
            : self::TIPO_ACCION_ENF_VISIBLE;

        return EnfCatalogo::query()
            ->where('tipo', 'tipo_accion_enf')
            ->where('nombre', $nombre)
            ->where('activo', true)
            ->value('id');
    }

