 268	                            carrerasOptions: @js($carrerasOptions),
 269	                            selectedCentros: @js(array_values(array_filter(array_map('strval', (array) old('centro_facultad_ids', old('centro_facultad_id') ? [old('centro_facultad_id')] : []))))),
 270	                            selectedDepartamentos: @js(array_values(array_filter(array_map('strval', (array) old('departamento_academico_ids', old('departamento_academico_id') ? [old('departamento_academico_id')] : []))))),
 271	                            selectedCarreras: @js(array_values(array_filter(array_map('strval', (array) old('carrera_ids', old('carrera_id') ? [old('carrera_id')] : []))))),
 272	                            init() {
 273	                                const key = this.$root.closest('form')?.dataset.storageKey;
 274	                                if (key) {
 275	                                    try {
 276	                                        const initial = window.__enfInitialDrafts?.[key] || {};
 277	                                        const stored = JSON.parse(window.localStorage.getItem(key) || '{}');
 278	                                        const data = { ...initial, ...stored };
 279	                                        this.selectedCentros = this.normalized(data['centro_facultad_ids[]'] ?? (data.centro_facultad_id ? [data.centro_facultad_id] : this.selectedCentros));
 280	                                        this.selectedDepartamentos = this.normalized(data['departamento_academico_ids[]'] ?? (data.departamento_academico_id ? [data.departamento_academico_id] : this.selectedDepartamentos));
 281	                                        this.selectedCarreras = this.normalized(data['carrera_ids[]'] ?? (data.carrera_id ? [data.carrera_id] : this.selectedCarreras));
 282	                                    } catch (error) {}
 283	                                }
 284	                                this.filterSelections();
 285	                            },
 286	                            normalized(values) {
 287	                                return Array.isArray(values) ? values.map(String).filter(Boolean) : [];
 288	                            },
 289	                            optionEntries(options, search = '') {
 290	                                const term = search.trim().toLowerCase();
 291	                                return Object.entries(options || {}).filter(([id, value]) => {
 292	                                    const label = typeof value === 'object' ? value.label : value;
 293	                                    return !term || String(label).toLowerCase().includes(term);
 294	                                });
 295	                            },
 296	                            departamentoEntries() {
 297	                                if (!this.selectedCentros.length) {
 298	                                    return [];
 299	                                }
 300	                                return this.optionEntries(this.departamentosOptions, this.searchDepartamentos)
 301	                                    .filter(([id, value]) => this.selectedCentros.includes(String(value.centro_facultad_id)));
 302	                            },
 303	                            carreraEntries() {
 304	                                if (!this.selectedCentros.length) {
 305	                                    return [];
 306	                                }
 307	                                return this.optionEntries(this.carrerasOptions, this.searchCarreras)
 308	                                    .filter(([id, value]) => {
 309	                                        const centroMatch = (value.centro_ids || []).some((centroId) => this.selectedCentros.includes(String(centroId)));
 310	                                        const departamentoMatch = !this.selectedDepartamentos.length
 311	                                            || (value.departamento_ids || []).some((departamentoId) => this.selectedDepartamentos.includes(String(departamentoId)));
 312	
 313	                                        return centroMatch && departamentoMatch;
 314	                                    });
 315	                            },
 316	                            toggle(listName, id) {
 317	                                id = String(id);
 318	                                const values = this[listName].map(String);
 319	                                const index = values.indexOf(id);
 320	                                if (index === -1) {
 321	                                    values.push(id);
 322	                                } else {
 323	                                    values.splice(index, 1);
 324	                                }
 325	                                this[listName] = values;
 326	                                this.filterSelections();
 327	                                this.notifyChange();
 328	                            },
 329	                            remove(listName, id) {
 330	                                id = String(id);
 331	                                this[listName] = this[listName].map(String).filter((value) => value !== id);
 332	                                this.filterSelections();
 333	                                this.notifyChange();
 334	                            },
 335	                            filterSelections() {
 336	                                const departamentoIds = this.departamentoEntries().map(([id]) => String(id));
 337	                                this.selectedDepartamentos = this.selectedDepartamentos.filter((id) => departamentoIds.includes(String(id)));
 338	
 339	                                const carreraIds = this.carreraEntries().map(([id]) => String(id));
 340	                                this.selectedCarreras = this.selectedCarreras.filter((id) => carreraIds.includes(String(id)));
 341	                            },
 342	                            isSelected(listName, id) {
 343	                                return this[listName].map(String).includes(String(id));
 344	                            },
 345	                            label(options, id) {
 346	                                const value = options[String(id)] ?? options[id] ?? id;
 347	                                return typeof value === 'object' ? value.label : value;
 348	                            },
 349	                            notifyChange() {
 350	                                this.$nextTick(() => this.$root.dispatchEvent(new Event('change', { bubbles: true })));
 351	                            },
