1023	                            init() {
1024	                                const key = this.$root.closest('form')?.dataset.storageKey;
1025	                                if (key) {
1026	                                    try {
1027	                                        const initial = window.__enfInitialDrafts?.[key] || {};
1028	                                        const stored = JSON.parse(window.localStorage.getItem(key) || '{}');
1029	                                        const data = { ...initial, ...stored };
1030	                                        this.selectedOds = this.normalized(data['ods_ids[]'] ?? this.selectedOds);
1031	                                        this.selectedMetas = this.normalized(data['meta_contribuye_ids[]'] ?? this.selectedMetas);
1032	                                    } catch (error) {}
1033	                                }
1034	                                this.filterSelectedMetas();
1035	                            },
1036	                            normalized(values) {
1037	                                return Array.isArray(values) ? values.map(String) : [];
1038	                            },
1039	                            optionEntries(options, search = '') {
1040	                                const term = search.trim().toLowerCase();
1041	                                return Object.entries(options || {}).filter(([id, value]) => {
1042	                                    const label = typeof value === 'object' ? value.label : value;
1043	                                    return !term || String(label).toLowerCase().includes(term);
1044	                                });
