1053	                            toggle(listName, id) {
1054	                                id = String(id);
1055	                                const values = this[listName].map(String);
1056	                                const index = values.indexOf(id);
1057	                                if (index === -1) {
1058	                                    values.push(id);
1059	                                } else {
1060	                                    values.splice(index, 1);
1061	                                }
1062	                                this[listName] = values;
1063	                                if (listName === 'selectedOds') {
1064	                                    this.filterSelectedMetas();
1065	                                }
1066	                                this.notifyChange();
1067	                            },
1068	                            remove(listName, id) {
1069	                                id = String(id);
